 19	type Agent struct {
 20		LookPath func(string) (string, error)
 21	}
 22	
 23	func New() *Agent {
 24		return &Agent{LookPath: exec.LookPath}
 25	}
 26	
 27	func (a *Agent) Info() protocol.InfoResponse {
 28		hookNames := make([]string, 0, len(hookSpecs))
 29		for _, spec := range hookSpecs {
 30			hookNames = append(hookNames, spec.HookName)
 31		}
 32		return protocol.InfoResponse{
 33			ProtocolVersion: protocol.ProtocolVersion,
 34			Name:            AgentName,
 35			Type:            AgentType,
 36			Description:     "Sarvam Code external agent integration for Entire",
 37			IsPreview:       true,
 38			ProtectedDirs:   []string{".sarvam"},
 39			HookNames:       hookNames,
 40			Capabilities: protocol.DeclaredCapabilities{
 41				Hooks:              true,
 42				TranscriptAnalyzer: true,
 43				CompactTranscript:  true,
 44				TokenCalculator:    true,
 45				UsesTerminal:       true,
 46			},
 47		}
 48	}
 49	
 50	func (a *Agent) Detect() protocol.DetectResponse {
 51		lookPath := a.LookPath
 52		if lookPath == nil {
 53			lookPath = exec.LookPath
 54		}
 55		if _, err := lookPath(sarvamBinary); err == nil {
 56			return protocol.DetectResponse{Present: true}
 57		}
 58		// A sessions store under SARVAM_HOME means the CLI has run before, even
 59		// when the binary is temporarily off PATH.
 60		if stat, err := os.Stat(filepath.Join(sarvamHome(), "sessions")); err == nil && stat.IsDir() {
 61			return protocol.DetectResponse{Present: true}
 62		}
 63		return protocol.DetectResponse{Present: false}
 64	}
