 73	// sarvamHome resolves $SARVAM_HOME, defaulting to ~/.sarvam.
 74	func sarvamHome() string {
 75		if v := os.Getenv("SARVAM_HOME"); v != "" {
 76			return v
 77		}
 78		home, err := os.UserHomeDir()
 79		if err != nil {
 80			return ".sarvam"
 81		}
 82		return filepath.Join(home, ".sarvam")
 83	}
