145	func (a *Agent) FormatResumeCommand(sessionID string) string {
146		if strings.TrimSpace(sessionID) == "" {
147			return "sarvam-code resume --last"
148		}
149		return "sarvam-code resume " + shellQuote(sessionID)
150	}
151	
152	func shellQuote(value string) string {
153		if value == "" {
154			return "''"
155		}
156		if strings.IndexFunc(value, func(r rune) bool {
157			return !isSafeShellQuoteRune(r)
158		}) == -1 {
159			return value
160		}
161		return "'" + strings.ReplaceAll(value, "'", "'\\''") + "'"
162	}
163	
164	func isSafeShellQuoteRune(r rune) bool {
165		return r == '-' || r == '_' || r == '.' || r == ':' ||
166			(r >= '0' && r <= '9') ||
167			(r >= 'a' && r <= 'z') ||
168			(r >= 'A' && r <= 'Z')
169	}
170	
171	// safeFilename maps a session ID onto a filename-safe string. Session IDs are
172	// UUIDs in practice, but the protocol accepts any string: common safe
173	// punctuation is preserved so the ID stays greppable in resolved paths, and
174	// anything hostile — including Windows reserved device names, which are not
175	// valid files there even with an extension — collapses to a hash instead of
176	// reaching the filesystem. Colons are not safe punctuation: they are path
177	// separators or ADS markers on Windows.
178	func safeFilename(sessionID string) string {
179		original := strings.TrimSpace(sessionID)
180		if original == "" {
181			return stubSessionID
182		}
183		var b strings.Builder
184		for _, r := range original {
185			switch {
186			case r >= '0' && r <= '9', r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z':
187				b.WriteRune(r)
188			case r == '-' || r == '_' || r == '.':
189				b.WriteRune(r)
190			default:
191				b.WriteByte('_')
192			}
193		}
194		out := strings.Trim(b.String(), "._")
195		if out == "" {
196			return stubSessionID
197		}
198		if out == original && !isWindowsDeviceName(out) {
199			return out
200		}
201		sum := sha256.Sum256([]byte(original))
202		return fmt.Sprintf("~%x", sum[:16])
203	}
204	
205	// isWindowsDeviceName reports whether the (already sanitized) name collides
206	// with a reserved DOS device: CON, PRN, AUX, NUL, COM1-9, LPT1-9,
207	// case-insensitively. Writing "<name>.jsonl" against these is not a real
208	// file on Windows, so they always take the hashed form.
209	func isWindowsDeviceName(name string) bool {
210		upper := strings.ToUpper(name)
211		switch upper {
212		case "CON", "PRN", "AUX", "NUL":
213			return true
214		}
215		if len(upper) == 4 {
216			switch {
217			case strings.HasPrefix(upper, "COM") && upper[3] >= '1' && upper[3] <= '9':
218				return true
219			case strings.HasPrefix(upper, "LPT") && upper[3] >= '1' && upper[3] <= '9':
220				return true
221			}
222		}
223		return false
224	}
225	
226	// sessionIDAndRef picks the session reference for a read: an explicit ref
227	// wins, then the native rollout for the ID, then the deterministic path.
228	func (a *Agent) sessionIDAndRef(input *protocol.HookInputJSON) (string, string) {
229		sessionID := stubSessionID
230		if input != nil && strings.TrimSpace(input.SessionID) != "" {
231			sessionID = input.SessionID
232		}
233		if input != nil && strings.TrimSpace(input.SessionRef) != "" {
234			return sessionID, input.SessionRef
235		}
236		return sessionID, a.ResolveSessionFile("", sessionID)
237	}
238	
239	// ReadSession rebuilds the AgentSession envelope from the transcript at the
240	// session ref. Native data is the raw rollout JSONL; modified files are
241	// derived from it on the fly.
242	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
243		sessionID, sessionRef := a.sessionIDAndRef(input)
244		data, err := os.ReadFile(sessionRef)
245		if errors.Is(err, os.ErrNotExist) {
246			data = nil
247		} else if err != nil {
248			return protocol.AgentSessionJSON{}, err
249		}
250		modifiedFiles, _, err := a.ExtractModifiedFiles(sessionRef, 0)
251		if errors.Is(err, os.ErrNotExist) {
252			modifiedFiles = nil
253		} else if err != nil {
254			return protocol.AgentSessionJSON{}, err
255		}
256		return protocol.AgentSessionJSON{
257			SessionID:     sessionID,
258			AgentName:     AgentName,
259			RepoPath:      protocol.RepoRoot(),
260			SessionRef:    sessionRef,
261			StartTime:     time.Now().UTC().Format(time.RFC3339),
262			NativeData:    data,
263			ModifiedFiles: modifiedFiles,
264			NewFiles:      []string{},
265			DeletedFiles:  []string{},
266		}, nil
267	}
268	
269	// WriteSession persists native session bytes at the ref Entire resolved —
270	// but never over sarvam's own rollout store. A native rollout that exists
271	// is sarvam's append-only transcript; replacing it with an entire-captured
272	// snapshot would truncate live appends or clobber history, which redaction
273	// cannot undo, so rollout-shaped targets are refused when present. A
274	// rollout-shaped ref that does not exist is the restore case — Entire
275	// recreating a captured snapshot on a fresh clone — and is created once,
276	// exclusively, so a native rollout appearing concurrently still wins. The
277	// ref the CLI's restore resolves on a fresh clone is not rollout-shaped,
278	// though: it is the deterministic fallback (<dir>/<id>.jsonl), and written
279	// verbatim it would be a file sarvam-code resume never discovers (resume
280	// scans for rollout-*-<id>.jsonl), so that exact ref is redirected to the
281	// native-shaped path derived from the snapshot's own session_meta. An empty
282	// payload is not a snapshot at all, and an empty ref resolves to the
283	// deterministic store path rather than ResolveSessionFile, which prefers
284	// the native file.
285	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
286		if len(session.NativeData) == 0 {
287			return errEmptySessionData
288		}
289		ref := strings.TrimSpace(session.SessionRef)
290		if ref == "" {
291			if strings.TrimSpace(session.SessionID) == "" {
292				return errMissingSessionRef
293			}
294			ref = a.storePath(session.SessionID)
295		}
296		if !isNativeRolloutPath(ref) && isDeterministicFallbackRef(ref, session.SessionID) {
297			if restored := restoredRolloutRef(ref, session.SessionID, session.NativeData); restored != "" {
298				ref = restored
299			}
300		}
301		if isNativeRolloutPath(ref) {
302			if err := os.MkdirAll(filepath.Dir(ref), 0o700); err != nil {
303				return err
304			}
305			f, err := os.OpenFile(ref, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
306			if err != nil {
307				if os.IsExist(err) {
308					return errNativeRolloutWrite
309				}
310				return err
311			}
312			if _, err := f.Write(session.NativeData); err != nil {
313				_ = f.Close()
314				// A failed restore must not leave a partial file masquerading
315				// as a native rollout.
316				_ = os.Remove(ref)
317				return err
318			}
319			if err := f.Close(); err != nil {
320				_ = os.Remove(ref)
321				return err
322			}
323			return nil
324		}
325		if err := os.MkdirAll(filepath.Dir(ref), 0o700); err != nil {
326			return err
327		}
328		return os.WriteFile(ref, session.NativeData, 0o600)
329	}
330	
331	// storePath is the deterministic in-store location for a session ID. It
332	// deliberately bypasses ResolveSessionFile, which returns the native
333	// rollout whenever one exists.
334	func (a *Agent) storePath(sessionID string) string {
335		dir, _ := a.GetSessionDir("")
336		return filepath.Join(dir, safeFilename(sessionID)+".jsonl")
337	}
338	
339	// isDeterministicFallbackRef reports whether ref is the <dir>/<id>.jsonl
340	// fallback resolve-session-file predicts when no rollout exists — the shape
341	// the CLI's restore resolves on a fresh clone. Only that ref is redirected
342	// to a discoverable path; anything else a caller names is written where it
343	// says.
344	func isDeterministicFallbackRef(ref, sessionID string) bool {
345		sessionID = strings.TrimSpace(sessionID)
346		return sessionID != "" && filepath.Base(ref) == safeFilename(sessionID)+".jsonl"
347	}
348	
349	// restoredRolloutRef derives the native rollout path a restore should land
350	// at: the snapshot's own session_meta timestamp picks the date directory and
351	// the file name, so sarvam-code resume — which scans for
352	// rollout-*-<id>.jsonl under sessions/YYYY/MM/DD/ — discovers the restored
353	// session. This mirrors the CLI Codex agent's restoredRolloutPath for the
354	// same store layout. Returns "" when the snapshot carries no parseable
355	// session_meta; the caller then writes the ref as given.
356	func restoredRolloutRef(ref, sessionID string, nativeData []byte) string {
357		sessionID = strings.TrimSpace(sessionID)
358		if sessionID == "" {
359			return ""
360		}
361		first := nativeData
362		if i := bytes.IndexByte(nativeData, '\n'); i >= 0 {
363			first = first[:i]
364		}
365		var meta rolloutLine
366		if json.Unmarshal(bytes.TrimSpace(first), &meta) != nil || meta.Type != "session_meta" {
367			return ""
368		}
369		start, err := time.Parse(time.RFC3339, strings.TrimSpace(meta.Timestamp))
370		if err != nil {
371			return ""
372		}
373		start = start.UTC()
374		dayPath := filepath.Join(filepath.Dir(ref), start.Format("2006"), start.Format("01"), start.Format("02"))
375		name := fmt.Sprintf("rollout-%s-%s.jsonl", start.Format("2006-01-02T15-04-05"), safeFilename(sessionID))
376		return filepath.Join(dayPath, name)
377	}
378	
379	// isNativeRolloutPath reports whether the path names one of sarvam's own
380	// rollout transcripts (rollout-<timestamp>-<thread>.jsonl), which write
381	// targets must never touch.
382	func isNativeRolloutPath(path string) bool {
383		base := filepath.Base(path)
384		return strings.HasPrefix(base, "rollout-") && strings.HasSuffix(base, ".jsonl")
385	}
386	
387	// ReadTranscript returns the raw transcript bytes at the ref. Entire runs its
388	// own redaction over the result and hands a temp copy back through
389	// compact-transcript for the Entire-facing projection.
390	func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
391		return os.ReadFile(sessionRef)
392	}
393	
394	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
395		if maxSize <= 0 {
396			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
397		}
398		if len(content) == 0 {
399			return [][]byte{{}}, nil
400		}
401		var chunks [][]byte
402		for start := 0; start < len(content); start += maxSize {
403			end := start + maxSize
404			if end > len(content) {
405				end = len(content)
406			}
407			chunk := make([]byte, end-start)
408			copy(chunk, content[start:end])
409			chunks = append(chunks, chunk)
410		}
411		return chunks, nil
412	}
413	
414	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
415		total := 0
416		for _, chunk := range chunks {
417			total += len(chunk)
418		}
419		out := make([]byte, 0, total)
420		for _, chunk := range chunks {
421			out = append(out, chunk...)
422		}
423		return out, nil
424	}
