 14	// ParseHook converts a sarvam lifecycle hook payload into a protocol event.
 15	//
 16	// Two input shapes reach this code path:
 17	//
 18	//   - the native payload sarvam pipes to the installed command (identified by
 19	//     its "hook_event_name" field), forwarded verbatim by Entire, and
 20	//   - the protocol HookInputJSON the compliance harness (and legacy callers)
 21	//     send, identified by "hook_type".
 22	//
 23	// Events with no protocol representation return a nil event; the handler
 24	// prints "null" and Entire treats them as non-lifecycle.
 25	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
 26		trimmed := bytes.TrimSpace(input)
 27		if len(trimmed) == 0 {
 28			return nil, nil
 29		}
 30	
 31		var native sarvamHookInput
 32		if err := json.Unmarshal(trimmed, &native); err != nil {
 33			return nil, fmt.Errorf("parse sarvam hook input: %w", err)
 34		}
 35	
 36		if strings.TrimSpace(native.HookEventName) == "" {
 37			// Protocol-shaped input: map it onto the native structure so both
 38			// shapes flow through one path.
 39			var hookInput protocol.HookInputJSON
 40			if err := json.Unmarshal(trimmed, &hookInput); err != nil {
 41				return nil, fmt.Errorf("parse hook input: %w", err)
 42			}
 43			native.HookEventName = hookInput.HookType
 44			if native.HookEventName == "" {
 45				native.HookEventName = hookName
 46			}
 47			native.SessionID = hookInput.SessionID
 48			native.TranscriptPath = hookInput.SessionRef
 49			native.Prompt = hookInput.UserPrompt
 50			native.ToolName = hookInput.ToolName
 51			native.ToolUseID = hookInput.ToolUseID
 52			native.ToolInput = hookInput.ToolInput
 53		}
 54	
 55		event := sarvamEventName(native.HookEventName, hookName)
 56		metadata := hookMetadata(native)
 57	
 58		switch event {
 59		case "SessionStart":
 60			return &protocol.EventJSON{
 61				Type:       1,
 62				SessionID:  a.sessionID(native),
 63				SessionRef: a.sessionRef(native),
 64				Model:      native.Model,
 65				Timestamp:  timestampNow(),
 66				Metadata:   metadata,
 67			}, nil
 68		case "UserPromptSubmit":
 69			if strings.TrimSpace(native.Prompt) == "" {
 70				return nil, nil
 71			}
 72			return &protocol.EventJSON{
 73				Type:       2,
 74				SessionID:  a.sessionID(native),
 75				SessionRef: a.sessionRef(native),
 76				Prompt:     native.Prompt,
 77				Model:      native.Model,
 78				Timestamp:  timestampNow(),
 79				Metadata:   metadata,
 80			}, nil
 81		case "Stop":
 82			return &protocol.EventJSON{
 83				Type:            3,
 84				SessionID:       a.sessionID(native),
 85				SessionRef:      a.sessionRef(native),
 86				Model:           native.Model,
 87				Timestamp:       timestampNow(),
 88				ResponseMessage: native.LastAssistantMessage,
 89				Metadata:        metadata,
 90			}, nil
 91		case "PostCompact":
 92			return &protocol.EventJSON{
 93				Type:       4,
 94				SessionID:  a.sessionID(native),
 95				SessionRef: a.sessionRef(native),
 96				Model:      native.Model,
 97				Timestamp:  timestampNow(),
 98				Metadata:   metadata,
 99			}, nil
100		default:
101			// PreCompact (a legacy install may still fire it — compaction is
102			// reported once, from PostCompact), PreToolUse, PostToolUse,
103			// PermissionRequest, and anything unknown: no lifecycle
104			// significance for Entire.
105			return nil, nil
106		}
107	}
