109	func (a *Agent) sessionID(native sarvamHookInput) string {
110		if id := strings.TrimSpace(native.SessionID); id != "" {
111			return id
112		}
113		return stubSessionID
114	}
115	
116	func (a *Agent) sessionRef(native sarvamHookInput) string {
117		if path := strings.TrimSpace(native.TranscriptPath); path != "" {
118			return path
119		}
120		return a.ResolveSessionFile("", native.SessionID)
121	}
122	
123	func timestampNow() string {
124		return time.Now().UTC().Format(time.RFC3339)
125	}
126	
127	// sarvamEventName resolves the native event from the payload, falling back to
128	// the hook name Entire passed. Payloads may carry the PascalCase native event
129	// ("SessionStart") or the kebab-case protocol name ("session-start"); both map
130	// onto the installed native event.
131	func sarvamEventName(fromPayload, fromFlag string) string {
132		for _, spec := range hookSpecs {
133			if fromPayload == spec.SarvamEvent || fromPayload == spec.HookName {
134				return spec.SarvamEvent
135			}
136		}
137		if name := strings.TrimSpace(fromPayload); name != "" {
138			return name
139		}
140		for _, spec := range hookSpecs {
141			if fromFlag == spec.HookName || fromFlag == spec.SarvamEvent {
142				return spec.SarvamEvent
143			}
144		}
145		return fromFlag
146	}
147	
148	func hookMetadata(native sarvamHookInput) map[string]string {
149		metadata := map[string]string{
150			"agent":           AgentName,
151			"hook_event_name": native.HookEventName,
152		}
153		if native.CWD != "" {
154			metadata["cwd"] = native.CWD
155		}
156		if native.Source != "" {
157			metadata["source"] = native.Source
158		}
159		if native.Trigger != "" {
160			metadata["trigger"] = native.Trigger
161		}
162		if native.PermissionMode != "" {
163			metadata["permission_mode"] = native.PermissionMode
164		}
165		if native.TurnID != "" {
166			metadata["turn_id"] = native.TurnID
167		}
168		return metadata
169	}
