171	// hookCommand renders the command written into .sarvam/config.toml. It names
172	// the binary as plain `entire` so it resolves through PATH when the hook
173	// runs; baking in an absolute path would put a machine-specific path into a
174	// repo-local config that is routinely committed.
175	func hookCommand(hookName string) string {
176		return fmt.Sprintf("sh -c 'if command -v entire >/dev/null 2>&1; then entire hooks %s %s >/dev/null 2>&1 || true; fi'", AgentName, hookName)
177	}
178	
179	// projectConfigPath is the repo-local sarvam config that carries hook
180	// declarations. Hook *state* (trust) lives in the user config and stays
181	// untouched: grant it through the sarvam TUI's /hooks review, never here.
182	func projectConfigPath() string {
183		return filepath.Join(protocol.RepoRoot(), ".sarvam", "config.toml")
184	}
185	
186	func (a *Agent) InstallHooks(localDev bool, force bool) (int, error) {
187		_ = localDev // hook state is user-managed; there is no dev path to point at
188		path := projectConfigPath()
189		entries := make([]configHookEntry, 0, len(hookSpecs))
190		for _, spec := range hookSpecs {
191			entries = append(entries, configHookEntry{
192				Event:   spec.SarvamEvent,
193				Name:    spec.EntryName,
194				Command: hookCommand(spec.HookName),
195			})
196		}
197		return upsertHookEntries(path, entries, force)
198	}
199	
200	func (a *Agent) UninstallHooks() error {
201		return removeHookEntries(projectConfigPath())
202	}
203	
204	func (a *Agent) AreHooksInstalled() bool {
205		path := projectConfigPath()
206		for _, spec := range hookSpecs {
207			if !hookEntryInstalled(path, spec.SarvamEvent, hookCommand(spec.HookName)) {
208				return false
209			}
210		}
211		return true
212	}

