 50	func (a *Agent) Detect() protocol.DetectResponse {
 51		lookPath := a.LookPath
 52		if lookPath == nil {
 53			lookPath = exec.LookPath
 54		}
 55		if _, err := lookPath(sarvamBinary); err == nil {
 56			return protocol.DetectResponse{Present: true}
 57		}
 58		// A sessions store under SARVAM_HOME means the CLI has run before, even
 59		// when the binary is temporarily off PATH.
 60		if stat, err := os.Stat(filepath.Join(sarvamHome(), "sessions")); err == nil && stat.IsDir() {
 61			return protocol.DetectResponse{Present: true}
 62		}
 63		return protocol.DetectResponse{Present: false}
 64	}
