 85	// GetSessionDir returns the root of sarvam's session store. The CLI treats
 86	// this directory as the store root and refuses any path resolved outside it
 87	// (ErrOutsideSessionStore), while the store itself is date-partitioned
 88	// (sessions/YYYY/MM/DD/), so the root — the answer the CLI's own Codex agent
 89	// gives for the same layout — is what keeps resolve-session-file's
 90	// whole-tree glob inside the store for sessions from earlier days.
 91	func (a *Agent) GetSessionDir(repoPath string) (string, error) {
 92		_ = repoPath // kept for interface symmetry; the store is global
 93		return filepath.Join(sarvamHome(), "sessions"), nil
 94	}
