  1	package sarvam
  2	
  3	import (
  4		"bufio"
  5		"encoding/json"
  6		"errors"
  7		"io"
  8		"os"
  9		"regexp"
 10		"sort"
 11		"strings"
 12	)
 13	
 14	// The rollout JSONL is append-only, and Entire tracks progress with the
 15	// (position, offset) pair this analyzer produces, so offsets are record
 16	// indexes: get-transcript-position returns the number of physical lines, and
 17	// extract --offset is the line index to resume from.
 18	
 19	// readRolloutLines parses the rollout JSONL of a live transcript:
 20	// unparseable lines become empty placeholders so line offsets stay aligned
 21	// with the physical file, and a final line that is still being written (no
 22	// trailing newline) is excluded: the position must not cover a record whose
 23	// remaining bytes arrive later, or the next read at that offset would skip
 24	// them.
 25	func readRolloutLines(path string) ([]rolloutLine, error) {
 26		return scanRolloutLines(path, false)
 27	}
 28	
 29	// readFinishedRolloutLines parses a rollout snapshot whose writer is done.
 30	// Redaction does not guarantee the trailing newline survives, and a missing
 31	// one must not drop the final record — typically the last assistant reply —
 32	// from the compacted transcript, so an unterminated final line is kept when
 33	// it parses as valid JSON. The strict rule stays with the live-transcript
 34	// readers.
 35	func readFinishedRolloutLines(path string) ([]rolloutLine, error) {
 36		return scanRolloutLines(path, true)
 37	}
 38	
 39	// scanRolloutLines reads records with no fixed per-line cap — one record can
 40	// embed a whole tool output, and a size cap would corrupt every offset after
 41	// it. In the lenient mode a final unterminated line counts when it parses.
 42	func scanRolloutLines(path string, lenientFinal bool) ([]rolloutLine, error) {
 43		f, err := os.Open(path)
 44		if err != nil {
 45			return nil, err
 46		}
 47		defer func() { _ = f.Close() }()
 48	
 49		var lines []rolloutLine
 50		reader := bufio.NewReaderSize(f, 64*1024)
 51		for {
 52			raw, readErr := reader.ReadBytes('\n')
 53			if len(raw) > 0 {
 54				line := strings.TrimSpace(string(raw))
 55				var record rolloutLine
 56				parses := json.Unmarshal([]byte(line), &record) == nil
 57				if !parses {
 58					record = rolloutLine{}
 59				}
 60				if readErr == nil || (lenientFinal && parses) {
 61					lines = append(lines, record)
 62				}
 63			}
 64			if readErr != nil {
 65				if errors.Is(readErr, io.EOF) {
 66					return lines, nil
 67				}
 68				return lines, readErr
 69			}
 70		}
 71	}
 72	
 73	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
 74		lines, err := readRolloutLines(path)
 75		if errors.Is(err, os.ErrNotExist) {
 76			return 0, nil
 77		}
 78		if err != nil {
 79			return 0, err
 80		}
 81		return len(lines), nil
 82	}
 83	
 84	func clampOffset(offset, length int) int {
 85		if offset < 0 {
 86			return 0
 87		}
 88		if offset > length {
 89			return length
 90		}
 91		return offset
 92	}
 93	
 94	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
 95		lines, err := readRolloutLines(path)
 96		if errors.Is(err, os.ErrNotExist) {
 97			return nil, 0, nil
 98		}
 99		if err != nil {
100			return nil, 0, err
101		}
102		start := clampOffset(offset, len(lines))
103	
104		seen := map[string]struct{}{}
105		for _, line := range lines[start:] {
106			if line.Type != rolloutLineTypeResponseItem {
107				continue
108			}
109			var call rolloutFunctionCall
110			if json.Unmarshal(line.Payload, &call) != nil || call.Type != "function_call" {
111				continue
112			}
113			for _, file := range pathsFromToolCall(call) {
114				normalized := strings.TrimSpace(file)
115				if normalized != "" {
116					seen[normalized] = struct{}{}
117				}
118			}
119		}
120		files := make([]string, 0, len(seen))
121		for file := range seen {
122			files = append(files, file)
123		}
124		sort.Strings(files)
125		return files, len(lines), nil
126	}
127	
128	// pathsFromToolCall extracts the file paths a tool call writes to.
129	// write_file/edit_file carry "path"; exec_command carries the shell under
130	// "cmd" (the key live rollouts use; older releases used "command"), whose
131	// redirects are best-effort parsed. Read-only tools are deliberately
132	// unlisted: a read is not a modification, and a generic path-key fallback
133	// would report read_file targets as writes.
134	func pathsFromToolCall(call rolloutFunctionCall) []string {
135		var args map[string]any
136		if json.Unmarshal([]byte(call.Arguments), &args) != nil {
137			return nil
138		}
139		switch call.Name {
140		case "write_file":
141			return stringField(args, "path")
142		case "edit_file", "apply_patch", "edit":
143			var paths []string
144			paths = append(paths, stringField(args, "path")...)
145			paths = append(paths, stringField(args, "file_path")...)
146			return paths
147		case "exec_command":
148			command, _ := args["cmd"].(string)
149			if command == "" {
150				command, _ = args["command"].(string)
151			}
152			return pathsFromShellCommand(command)
153		default:
154			return nil
155		}
156	}
157	
158	func stringField(args map[string]any, key string) []string {
159		value, ok := args[key].(string)
160		if !ok || strings.TrimSpace(value) == "" {
161			return nil
162		}
163		return []string{value}
164	}
165	
166	func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
167		lines, err := readRolloutLines(sessionRef)
168		if errors.Is(err, os.ErrNotExist) {
169			return nil, nil
170		}
171		if err != nil {
172			return nil, err
173		}
174		start := clampOffset(offset, len(lines))
175	
176		var prompts []string
177		for _, line := range lines[start:] {
178			if line.Type != rolloutLineTypeResponseItem {
179				continue
180			}
181			var message rolloutMessage
182			if json.Unmarshal(line.Payload, &message) != nil || message.Role != roleUser {
183				continue
184			}
185			text := messageText(message, "input_text")
186			if text == "" || isHarnessContext(text) {
187				continue
188			}
189			prompts = append(prompts, text)
190		}
191		return prompts, nil
192	}
193	
194	// isHarnessContext filters the leading environment block sarvam records as a
195	// user item — it is injected context, not a human prompt.
196	func isHarnessContext(text string) bool {
197		return strings.HasPrefix(strings.TrimSpace(text), "<environment_context>")
198	}
199	
200	// shellPathPatterns best-effort extract written files from shell commands:
201	// redirects, tee, and touch are the reliable signals in practice. The append
202	// form comes first in the alternation: Go's regexp is leftmost-first, so
203	// (>|>>) would match the single ">" of ">>" and capture ">" as the path.
204	var shellPathPatterns = []*regexp.Regexp{
205		regexp.MustCompile(`(?:^|\s)(?:>>|>)\s*'?"?([^'"\s;&|]+)`),
206		regexp.MustCompile(`(?:^|\s)tee\s+(?:-a\s+)?'?"?([^'"\s;&|]+)`),
207		regexp.MustCompile(`(?:^|\s)touch\s+'?"?([^'"\s;&|]+)`),
208	}
209	
210	func pathsFromShellCommand(command string) []string {
211		if strings.TrimSpace(command) == "" {
212			return nil
213		}
214		var paths []string
215		for _, pattern := range shellPathPatterns {
216			for _, match := range pattern.FindAllStringSubmatch(command, -1) {
217				if len(match) > 1 {
218					path := strings.Trim(match[1], `"'`)
219					if isDevicePath(path) {
220						continue
221					}
222					paths = append(paths, path)
223				}
224			}
225		}
226		return paths
227	}
228	
229	// isDevicePath filters redirect targets that are device files rather than
230	// workspace paths: /dev/null dominates real usage, and /dev/std* and
231	// /dev/fd/* round out the family.
232	func isDevicePath(path string) bool {
233		return path == "/dev" || strings.HasPrefix(path, "/dev/")
234	}
235	
236	// messageText concatenates the text blocks of the given type.
237	func messageText(message rolloutMessage, blockType string) string {
238		var b strings.Builder
239		for _, block := range message.Content {
240			if block.Type == blockType && block.Text != "" {
241				if b.Len() > 0 {
242					b.WriteByte('\n')
243				}
244				b.WriteString(block.Text)
245			}
246		}
247		return b.String()
248	}
249	
250	// ExtractSummary returns the agent's last assistant message as the session
251	// summary, mirroring the other external agents: it is the natural "what did
252	// the agent do" line for a checkpoint.
253	func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
254		lines, err := readRolloutLines(sessionRef)
255		if errors.Is(err, os.ErrNotExist) {
256			return "", false, nil
257		}
258		if err != nil {
259			return "", false, err
260		}
261		for i := len(lines) - 1; i >= 0; i-- {
262			line := lines[i]
263			if line.Type != rolloutLineTypeResponseItem {
264				continue
265			}
266			var message rolloutMessage
267			if json.Unmarshal(line.Payload, &message) != nil || message.Role != roleAssistant {
268				continue
269			}
270			if text := messageText(message, "output_text"); strings.TrimSpace(text) != "" {
271				return text, true, nil
272			}
273		}
274		return "", false, nil
275	}
  1	package sarvam
  2	
  3	import (
  4		"bufio"
  5		"bytes"
  6		"encoding/json"
  7		"errors"
  8		"io"
  9		"strings"
 10	
 11		"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
 12	)
 13	
 14	// CalculateTokens sums per-API-call usage from token_count records at or
 15	// after the given line offset. Sarvam re-emits token_count events whose
 16	// total_token_usage repeats the previous event's total (432 of 911 events in
 17	// one sampled session), so per-event last_token_usage cannot be summed — that
 18	// roughly doubles the reported usage. The window's usage is instead the delta
 19	// between the cumulative total_token_usage of the last counted event and the
 20	// total as of the offset, and an event is an API call only when its total
 21	// advances.
 22	//
 23	// info.input_tokens includes info.cached_input_tokens, so the input bucket
 24	// reports the non-cached share and the cached share is reported as cache
 25	// reads. Events with a null info (rate-limit snapshots) change nothing.
 26	//
 27	// The records are event_msg lines in the rollout JSONL, so the token_count
 28	// payload is nested under "payload". The offset is a physical line index —
 29	// the same unit this agent's get-transcript-position and extract-* report,
 30	// and the unit Entire feeds back from them. Lines are read exactly the way
 31	// readRolloutLines reads them: with no fixed per-line cap — one record can
 32	// embed a whole tool output, and a size cap here would fail token usage for
 33	// the whole checkpoint — and a final line without a trailing newline is
 34	// excluded, so it is not counted now and recounted once its newline
 35	// arrives.
 36	func (a *Agent) CalculateTokens(transcript []byte, offset int) (protocol.TokenUsageResponse, error) {
 37		usage := protocol.TokenUsageResponse{
 38			CacheCreationTokens: 0,
 39			SubagentTokens:      nil,
 40		}
 41	
 42		reader := bufio.NewReaderSize(bytes.NewReader(transcript), 64*1024)
 43		index := 0
 44		prev := rolloutTokenUsage{}
 45		for {
 46			raw, readErr := reader.ReadBytes('\n')
 47			if readErr != nil {
 48				// A final unterminated line is not consumed by the transcript
 49				// position; counting it here would only recount it once its
 50				// newline arrives.
 51				if errors.Is(readErr, io.EOF) {
 52					return usage, nil
 53				}
 54				return protocol.TokenUsageResponse{}, readErr
 55			}
 56			index++
 57			line := strings.TrimSpace(string(raw))
 58			if line == "" {
 59				continue
 60			}
 61			var event rolloutLine
 62			if json.Unmarshal([]byte(line), &event) != nil || event.Type != "event_msg" {
 63				continue
 64			}
 65			var count rolloutTokenCount
 66			if json.Unmarshal(event.Payload, &count) != nil || count.Type != "token_count" {
 67				continue
 68			}
 69			if count.Info == nil {
 70				continue
 71			}
 72			total := count.Info.TotalTokenUsage
 73			if total == prev {
 74				// A re-emitted snapshot of the same cumulative total is not
 75				// another API call.
 76				continue
 77			}
 78			if index <= offset {
 79				prev = total
 80				continue
 81			}
 82			usage.APICallCount++
 83			usage.InputTokens += nonNegative(nonNegative(total.InputTokens-prev.InputTokens) - nonNegative(total.CachedInputTokens-prev.CachedInputTokens))
 84			usage.CacheReadTokens += nonNegative(total.CachedInputTokens - prev.CachedInputTokens)
 85			usage.OutputTokens += nonNegative(total.OutputTokens - prev.OutputTokens)
 86			prev = total
 87		}
 88	}
 89	
 90	// nonNegative clamps a usage delta at zero: cumulative totals only grow in a
 91	// well-formed rollout, and a malformed one must not report negative tokens.
 92	func nonNegative(delta int) int {
 93		if delta < 0 {
 94			return 0
 95		}
 96		return delta
 97	}

