101		Arguments string `json:"arguments"`
102	}
103	
104	type rolloutFunctionCallOutput struct {
105		Type   string `json:"type"` // "function_call_output"
106		CallID string `json:"call_id"`
107		Output string `json:"output"`
108	}
109	
110	type rolloutTokenCount struct {
111		Type string            `json:"type"` // "token_count"
112		Info *rolloutTokenInfo `json:"info"`
113	}
114	
115	type rolloutTokenInfo struct {
116		TotalTokenUsage rolloutTokenUsage `json:"total_token_usage"`
117		LastTokenUsage  rolloutTokenUsage `json:"last_token_usage"`
118	}
119	
120	type rolloutTokenUsage struct {
121		InputTokens           int `json:"input_tokens"`
122		CachedInputTokens     int `json:"cached_input_tokens"`
123		OutputTokens          int `json:"output_tokens"`
