  1	package sarvam
  2	
  3	import (
  4		"bytes"
  5		"encoding/base64"
  6		"encoding/json"
  7		"errors"
  8		"os"
  9		"strings"
 10	
 11		"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
 12	)
 13	
 14	// CompactTranscript projects the native rollout JSONL into Entire
 15	// Transcript Format: one v:1 unified record per line, the shape the
 16	// server's unified parser admits (isUnifiedTranscript requires a
 17	// top-level content array on the first line) and renders — the same
 18	// envelope qwen's and grok's compactors emit. The earlier projection
 19	// mirrored the wire shapes Entire's in-CLI compactor READS
 20	// ({"type","message":{…}}), which the server rejects: checkpoints stored
 21	// it, but the session page rendered nothing.
 22	//
 23	// Projection:
 24	//
 25	//	response_item message/user      -> user line, content [{"text": …}]
 26	//	  (input_text, minus the injected <environment_context> harness block)
 27	//	response_item message/assistant -> assistant line, content
 28	//	  [{"type":"text","text":…}]
 29	//	function_call                   -> assistant line with a tool_use block;
 30	//	  the matching function_call_output is nested as the block's result,
 31	//	  with a non-zero exec exit code reported as status "error"
 32	//
 33	// Developer messages, reasoning, and the event stream are dropped: none of
 34	// them belong in a checkpoint transcript.
 35	//
 36	// The input is a temp copy of an already-redacted snapshot, so a final line
 37	// without a trailing newline is finished data and is kept when it parses —
 38	// unlike the live-transcript readers, which must never cover a
 39	// half-written record.
 40	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
 41		lines, err := readFinishedRolloutLines(sessionRef)
 42		if err != nil {
 43			if os.IsNotExist(err) {
 44				lines = nil
 45			} else {
 46				return protocol.CompactTranscriptResponse{}, err
 47			}
 48		}
 49	
 50		// First pass: the CLI version from session_meta and each call's output,
 51		// so a tool_use block can nest the result that the rollout records as
 52		// a separate, later line.
 53		cliVersion := "unknown"
 54		toolResults := map[string]compactToolResult{}
 55		for _, line := range lines {
 56			if line.Type == "session_meta" {
 57				var meta struct {
 58					CLIVersion string `json:"cli_version"`
 59				}
 60				if json.Unmarshal(line.Payload, &meta) == nil && strings.TrimSpace(meta.CLIVersion) != "" {
 61					cliVersion = strings.TrimSpace(meta.CLIVersion)
 62				}
 63				continue
 64			}
 65			if line.Type != rolloutLineTypeResponseItem {
 66				continue
 67			}
 68			var probe struct {
 69				Type string `json:"type"`
 70			}
 71			if json.Unmarshal(line.Payload, &probe) != nil || probe.Type != "function_call_output" {
 72				continue
 73			}
 74			var output rolloutFunctionCallOutput
 75			if json.Unmarshal(line.Payload, &output) != nil {
 76				continue
 77			}
 78			toolResults[output.CallID] = compactToolResultFromOutput(output.Output)
 79		}
 80	
 81		var out bytes.Buffer
 82		for _, line := range lines {
 83			if line.Type != rolloutLineTypeResponseItem {
 84				continue
 85			}
 86			var probe struct {
 87				Type string `json:"type"`
 88			}
 89			if json.Unmarshal(line.Payload, &probe) != nil {
 90				continue
 91			}
 92			switch probe.Type {
 93			case "message":
 94				var message rolloutMessage
 95				if json.Unmarshal(line.Payload, &message) != nil {
 96					continue
 97				}
 98				switch message.Role {
 99				case roleUser:
100					text := messageText(message, "input_text")
101					if text == "" || isHarnessContext(text) {
102						continue
103					}
104					if err := writeCompactLine(&out, compactLine{
105						V:          1,
106						Agent:      AgentName,
107						CLIVersion: cliVersion,
108						Type:       roleUser,
109						TS:         line.Timestamp,
110						Content:    []compactUserTextBlock{{Text: text}},
111					}); err != nil {
112						return protocol.CompactTranscriptResponse{}, err
113					}
114				case roleAssistant:
115					text := messageText(message, "output_text")
116					if strings.TrimSpace(text) == "" {
117						continue
118					}
119					if err := writeCompactLine(&out, compactLine{
120						V:          1,
121						Agent:      AgentName,
122						CLIVersion: cliVersion,
123						Type:       roleAssistant,
124						TS:         line.Timestamp,
125						Content:    []compactAssistantTextBlock{{Type: "text", Text: text}},
126					}); err != nil {
127						return protocol.CompactTranscriptResponse{}, err
128					}
129				}
130			case "function_call":
131				var call rolloutFunctionCall
132				if json.Unmarshal(line.Payload, &call) != nil {
133					continue
134				}
135				block := compactToolUseBlock{
136					Type:  "tool_use",
137					ID:    call.CallID,
138					Name:  call.Name,
139					Input: decodeToolArguments(call.Arguments),
140				}
141				if result, ok := toolResults[call.CallID]; ok {
142					block.Result = &result
143				}
144				if err := writeCompactLine(&out, compactLine{
145					V:          1,
146					Agent:      AgentName,
147					CLIVersion: cliVersion,
148					Type:       roleAssistant,
149					TS:         line.Timestamp,
150					ID:         call.CallID,
151					Content:    []any{block},
152				}); err != nil {
153					return protocol.CompactTranscriptResponse{}, err
154				}
155			}
156		}
157	
158		if out.Len() == 0 {
159			return protocol.CompactTranscriptResponse{}, errors.New("compact transcript produced no output")
160		}
161		return protocol.CompactTranscriptResponse{
162			Transcript: base64.StdEncoding.EncodeToString(out.Bytes()),
163		}, nil
164	}
165	
166	// compactLine is one Entire Transcript Format record: the top-level
167	// content array the server's unified parser reads, with the v, agent and
168	// ts envelope qwen's compactor emits.
169	type compactLine struct {
170		V          int    `json:"v"`
171		Agent      string `json:"agent"`
172		CLIVersion string `json:"cli_version"`
173		Type       string `json:"type"`
174		TS         string `json:"ts,omitempty"`
175		ID         string `json:"id,omitempty"`
176		Content    any    `json:"content"`
177	}
178	
179	type compactUserTextBlock struct {
180		Text string `json:"text"`
181	}
182	
183	type compactAssistantTextBlock struct {
184		Type string `json:"type"`
185		Text string `json:"text"`
186	}
187	
188	type compactToolUseBlock struct {
189		Type   string             `json:"type"`
190		ID     string             `json:"id,omitempty"`
191		Name   string             `json:"name"`
192		Input  any                `json:"input,omitempty"`
193		Result *compactToolResult `json:"result,omitempty"`
194	}
195	
196	type compactToolResult struct {
197		Output string `json:"output"`
198		Status string `json:"status"`
199	}
200	
201	// compactToolResultFromOutput derives the status the way qwen's compactor
202	// does: the CLI wraps exec results in a {"output",...,"metadata"} envelope
203	// whose exit_code carries the command's fate — a non-zero code is an error,
204	// anything else success. The envelope is decoded whenever it carries a
205	// metadata object, empty output included (a failed `false` or a silent grep
206	// miss must not read as success); anything else is tool text kept verbatim,
207	// JSON-shaped or not.
208	func compactToolResultFromOutput(output string) compactToolResult {
209		var envelope struct {
210			Output   string          `json:"output"`
211			Metadata json.RawMessage `json:"metadata"`
212		}
213		if json.Unmarshal([]byte(output), &envelope) == nil && len(envelope.Metadata) > 0 {
214			var meta struct {
215				ExitCode int `json:"exit_code"`
216			}
217			if json.Unmarshal(envelope.Metadata, &meta) == nil && meta.ExitCode != 0 {
218				return compactToolResult{Output: envelope.Output, Status: "error"}
219			}
220			return compactToolResult{Output: envelope.Output, Status: "success"}
221		}
222		return compactToolResult{Output: output, Status: "success"}
223	}
224	
225	func writeCompactLine(buf *bytes.Buffer, line compactLine) error {
226		encoded, err := json.Marshal(line)
227		if err != nil {
228			return err
229		}
230		buf.Write(encoded)
231		buf.WriteByte('\n')
232		return nil
233	}
234	
235	// decodeToolArguments parses the JSON-encoded arguments string into an object;
236	// a non-object or unparseable payload is forwarded as-is.
237	func decodeToolArguments(arguments string) any {
238		trimmed := strings.TrimSpace(arguments)
239		if trimmed == "" {
240			return map[string]any{}
241		}
242		var value map[string]any
243		if err := json.Unmarshal([]byte(trimmed), &value); err != nil {
244			return trimmed
245		}
246		return value
247	}
