content.content:
  1	package protocol
  2	
  3	import (
  4		"encoding/json"
  5		"errors"
  6		"flag"
  7		"io"
  8		"os"
  9		"time"
 10	)
 11	
 12	var errNegativeOffset = errors.New("offset must not be negative")
 13	
 14	type sessionDirResolver interface {
 15		GetSessionDir(repoPath string) (string, error)
 16	}
 17	
 18	type sessionFileResolver interface {
 19		ResolveSessionFile(sessionDir, sessionID string) string
 20	}
 21	
 22	type sessionIDProvider interface {
 23		GetSessionID(*HookInputJSON) string
 24	}
 25	
 26	type sessionReader interface {
 27		ReadSession(*HookInputJSON) (AgentSessionJSON, error)
 28	}
 29	
 30	type sessionWriter interface {
 31		WriteSession(AgentSessionJSON) error
 32	}
 33	
 34	type transcriptReader interface {
 35		ReadTranscript(sessionRef string) ([]byte, error)
 36	}
 37	
 38	type transcriptChunker interface {
 39		ChunkTranscript(content []byte, maxSize int) ([][]byte, error)
 40		ReassembleTranscript(chunks [][]byte) ([]byte, error)
 41	}
 42	
 43	type transcriptCompactor interface {
 44		CompactTranscript(sessionRef string) (CompactTranscriptResponse, error)
 45	}
 46	
 47	type tokenCalculator interface {
 48		CalculateTokens(transcript []byte, offset int) (TokenUsageResponse, error)
 49	}
 50	
 51	type resumeFormatter interface {
 52		FormatResumeCommand(sessionID string) string
 53	}
 54	
 55	type hookParser interface {
 56		ParseHook(hookName string, input []byte) (*EventJSON, error)
 57		InstallHooks(localDev bool, force bool) (int, error)
 58		UninstallHooks() error
 59		AreHooksInstalled() bool
 60	}
 61	
 62	type transcriptAnalyzer interface {
 63		GetTranscriptPosition(path string) (int, error)
 64		ExtractModifiedFiles(path string, offset int) ([]string, int, error)
 65		ExtractPrompts(sessionRef string, offset int) ([]string, error)
 66		ExtractSummary(sessionRef string) (string, bool, error)
 67	}
 68	
 69	func WriteJSON(w io.Writer, v any) error {
 70		enc := json.NewEncoder(w)
 71		enc.SetEscapeHTML(false)
 72		return enc.Encode(v)
 73	}
 74	
 75	func ReadJSON[T any](r io.Reader) (*T, error) {
 76		var value T
 77		if err := json.NewDecoder(r).Decode(&value); err != nil {
 78			return nil, err
 79		}
 80		return &value, nil
 81	}
 82	
 83	func RepoRoot() string {
 84		if root := os.Getenv("ENTIRE_REPO_ROOT"); root != "" {
 85			return root
 86		}
 87		root, _ := os.Getwd()
 88		return root
 89	}
 90	
 91	func HandleGetSessionID(stdin io.Reader, stdout io.Writer, provider sessionIDProvider) error {
 92		input, err := ReadJSON[HookInputJSON](stdin)
 93		if err != nil {
 94			return err
 95		}
 96		return WriteJSON(stdout, SessionIDResponse{SessionID: provider.GetSessionID(input)})
 97	}
 98	
 99	func HandleGetSessionDir(args []string, stdout io.Writer, resolver sessionDirResolver) error {
100		fs := flag.NewFlagSet("get-session-dir", flag.ContinueOnError)
101		fs.SetOutput(io.Discard)
102		repoPath := fs.String("repo-path", "", "repo path")
103		if err := fs.Parse(args); err != nil {
104			return err
105		}
106		sessionDir, err := resolver.GetSessionDir(*repoPath)
107		if err != nil {
108			return err
109		}
110		return WriteJSON(stdout, SessionDirResponse{SessionDir: sessionDir})
111	}
112	
113	func HandleResolveSessionFile(args []string, stdout io.Writer, resolver sessionFileResolver) error {
114		fs := flag.NewFlagSet("resolve-session-file", flag.ContinueOnError)
115		fs.SetOutput(io.Discard)
116		sessionDir := fs.String("session-dir", "", "session dir")
117		sessionID := fs.String("session-id", "", "session id")
118		if err := fs.Parse(args); err != nil {
119			return err
120		}
121		return WriteJSON(stdout, SessionFileResponse{SessionFile: resolver.ResolveSessionFile(*sessionDir, *sessionID)})
122	}
123	
124	func HandleReadSession(stdin io.Reader, stdout io.Writer, reader sessionReader) error {
125		input, err := ReadJSON[HookInputJSON](stdin)
126		if err != nil {
127			return err
128		}
129		session, err := reader.ReadSession(input)
130		if err != nil {
131			return err
132		}
133		return WriteJSON(stdout, session)
134	}
135	
136	func HandleWriteSession(stdin io.Reader, writer sessionWriter) error {
137		session, err := ReadJSON[AgentSessionJSON](stdin)
138		if err != nil {
139			return err
140		}
141		return writer.WriteSession(*session)
142	}
143	
144	func HandleReadTranscript(args []string, stdout io.Writer, reader transcriptReader) error {
145		fs := flag.NewFlagSet("read-transcript", flag.ContinueOnError)
146		fs.SetOutput(io.Discard)
147		sessionRef := fs.String("session-ref", "", "session ref")
148		if err := fs.Parse(args); err != nil {
149			return err
150		}
151		data, err := reader.ReadTranscript(*sessionRef)
152		if err != nil {
153			return err
154		}
155		_, err = stdout.Write(data)
156		return err
157	}
158	
159	func HandleChunkTranscript(args []string, stdin io.Reader, stdout io.Writer, chunker transcriptChunker) error {
160		fs := flag.NewFlagSet("chunk-transcript", flag.ContinueOnError)
161		fs.SetOutput(io.Discard)
162		maxSize := fs.Int("max-size", 0, "max size")
163		if err := fs.Parse(args); err != nil {
164			return err
165		}
166		content, err := io.ReadAll(stdin)
167		if err != nil {
168			return err
169		}
170		chunks, err := chunker.ChunkTranscript(content, *maxSize)
171		if err != nil {
172			return err
173		}
174		return WriteJSON(stdout, ChunkResponse{Chunks: chunks})
175	}
176	
177	func HandleReassembleTranscript(stdin io.Reader, stdout io.Writer, chunker transcriptChunker) error {
178		input, err := ReadJSON[ChunkResponse](stdin)
179		if err != nil {
180			return err
181		}
182		data, err := chunker.ReassembleTranscript(input.Chunks)
183		if err != nil {
184			return err
185		}
186		_, err = stdout.Write(data)
187		return err
188	}
189	
190	func HandleCompactTranscript(args []string, stdout io.Writer, compactor transcriptCompactor) error {
191		fs := flag.NewFlagSet("compact-transcript", flag.ContinueOnError)
192		fs.SetOutput(io.Discard)
193		sessionRef := fs.String("session-ref", "", "session ref")
194		if err := fs.Parse(args); err != nil {
195			return err
196		}
197		compacted, err := compactor.CompactTranscript(*sessionRef)
198		if err != nil {
199			return err
200		}
201		return WriteJSON(stdout, compacted)
202	}
203	
204	func HandleCalculateTokens(args []string, stdin io.Reader, stdout io.Writer, calculator tokenCalculator) error {
205		fs := flag.NewFlagSet("calculate-tokens", flag.ContinueOnError)
206		fs.SetOutput(io.Discard)
207		offset := fs.Int("offset", 0, "byte offset")
208		if err := fs.Parse(args); err != nil {
209			return err
210		}
211		transcript, err := io.ReadAll(stdin)
212		if err != nil {
213			return err
214		}
215		if *offset < 0 {
216			return errNegativeOffset
217		}
218		usage, err := calculator.CalculateTokens(transcript, *offset)
219		if err != nil {
220			return err
221		}
222		return WriteJSON(stdout, usage)
223	}
224	
225	func HandleFormatResumeCommand(args []string, stdout io.Writer, formatter resumeFormatter) error {
226		fs := flag.NewFlagSet("format-resume-command", flag.ContinueOnError)
227		fs.SetOutput(io.Discard)
228		sessionID := fs.String("session-id", "", "session id")
229		if err := fs.Parse(args); err != nil {
230			return err
231		}
232		return WriteJSON(stdout, ResumeCommandResponse{Command: formatter.FormatResumeCommand(*sessionID)})
