   148	// copyTree copies a directory (or a single file) recursively. The keyring
   149	// is a handful of small credential files, so plain reads and writes
   150	// suffice.
   151	func copyTree(src, dst string) error {
   152		info, err := os.Stat(src)
   153		if err != nil {
   154			return err
   155		}
   156		if !info.IsDir() {
   157			return copyTreeFile(src, dst, info.Mode().Perm())
   158		}
   159		return filepath.WalkDir(src, func(path string, d fs.DirEntry, walkErr error) error {
   160			if walkErr != nil {
   161				return walkErr
   162			}
   163			rel, err := filepath.Rel(src, path)
   164			if err != nil {
   165				return err
   166			}
   167			target := filepath.Join(dst, rel)
   168			if d.IsDir() {
   169				return os.MkdirAll(target, 0o700)
   170			}
   171			entryInfo, err := d.Info()
   172			if err != nil {
   173				return err
   174			}
