   261	// seedSarvamHookTrust writes the [hooks.state] entries a completed /hooks
   262	// review would persist: enabled = true plus the CLI's trusted_hash for each
   263	// of the four hooks entire-agent-sarvam installs. Missing entries are
   264	// appended; existing state for other repos is left untouched.
   265	func seedSarvamHookTrust(repoDir string) error {
   266		configPath := sarvamUserConfigPath()
   267		if configPath == "" {
   268			return errors.New("cannot resolve the sarvam user config for hook trust pre-seeding")
   269		}
   270		canonical, err := filepath.EvalSymlinks(repoDir)
   271		if err != nil {
   272			canonical = repoDir
   273		}
   274	
   275		data, err := os.ReadFile(configPath)
   276		if err != nil && !os.IsNotExist(err) {
   277			return err
   278		}
   279		content := string(data)
