   281		var addition strings.Builder
   282		for _, state := range sarvamHookState {
   283			key := canonical + "/.sarvam/config.toml:" + state.Event + ":0:0"
   284			if strings.Contains(content, `"`+key+`"`) {
   285				continue
   286			}
   287			addition.WriteString("\n[hooks.state.\"" + key + "\"]\n")
   288			addition.WriteString("enabled = true\n")
   289			addition.WriteString("trusted_hash = \"" + state.Hash + "\"\n")
   290		}
   291		if addition.Len() == 0 {
   292			return nil
   293		}
   294		if err := os.MkdirAll(filepath.Dir(configPath), 0o755); err != nil {
   295			return err
   296		}
   297		mode := os.FileMode(0o600)
   298		if existing, err := os.Stat(configPath); err == nil {
   299			mode = existing.Mode().Perm()
   300		}
   301		if len(content) > 0 && !strings.HasSuffix(content, "\n") {
   302			content += "\n"
   303		}
   304		return os.WriteFile(configPath, []byte(content+addition.String()), mode)
   305	}
   306	
   307	// sarvamUserConfigPath resolves the CLI's user config carrying [hooks.state].
   308	func sarvamUserConfigPath() string {
   309		if v := os.Getenv("SARVAM_HOME"); v != "" {
   310			return filepath.Join(v, "config.toml")
   311		}
   312		home, err := os.UserHomeDir()
   313		if err != nil {
   314			return ""
   315		}
   316		return filepath.Join(home, ".sarvam", "config.toml")
   317	}
