cd /Users/peytonmontei/dev/entire/devenv/entireio/external-agents/.worktrees/sarvam-review/agents/entire-agent-sarvam && cat > internal/sarvam/zz_scratch_test.go <<'EOF'
package sarvam

import (
	"os"
	"path/filepath"
	"testing"
)

func TestScratch2(t *testing.T) {
	a := New()
	files := pathsFromShellCommand(`echo "a > b" && git commit -m "fix: x > y" && make &> build.log && cp a.txt b.txt && rm old.txt`)
	t.Logf("shell paths: %q", files)

	// big line + partial final line
	dir := t.TempDir()
	p := filepath.Join(dir, "rollout-x-abc.jsonl")
	big := make([]byte, 200000)
	for i := range big { big[i] = 'a' }
	content := `{"type":"session_meta","timestamp":"2026-01-01T00:00:00Z","payload":{}}` + "\n" +
		`{"type":"response_item","payload":{"type":"function_call","name":"write_file","call_id":"1","arguments":"{\"path\":\"x.txt\",\"contents\":\"` + string(big) + `\"}"}}` + "\n" +
		`{"type":"response_item","payload":{"type":"function_call","name":"write_file","call_id":"2","arguments":"{\"path\":\"partial.txt\"}"}}`
	os.WriteFile(p, []byte(content), 0o644)
	pos, err := a.GetTranscriptPosition(p)
	f, cur, err2 := a.ExtractModifiedFiles(p, 0)
	t.Logf("pos=%d err=%v files=%v cur=%d err=%v", pos, err, f, cur, err2)

	// token: cumulative reset (e.g. resumed process restarts totals)
	tok := `{"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":1000,"output_tokens":100}}}}
{"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":1000,"output_tokens":100}}}}
{"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":300,"output_tokens":30}}}}
{"type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":700,"output_tokens":60}}}}
`
	u, _ := a.CalculateTokens([]byte(tok), 0)
	t.Logf("tokens after reset: %+v", u)
}
EOF
go test ./internal/sarvam -run TestScratch2 -v 2>&1 | grep -v "^===" | head

